insert into public.curated_recipes
  (title,summary,category,source_name,source_url,suitable_for_elimination,servings,preparation_minutes,ingredients,instructions,attribution_note,phase_note,published)
values
('Aardappel-spinazie ontbijtpan','Hartige ontbijtpan met krokante aardappel, spinazie, ei en bieslook.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,25,E'400 g vastkokende aardappelen, in blokjes\n4 eieren\n100 g babyspinazie\n30 g geraspte oude kaas\n2 el bieslook, fijngesneden\n1½ el knoflook-geïnfuseerde olijfolie\n½ tl gerookt paprikapoeder\nPeper en zout',E'1. Kook de aardappelblokjes 7 minuten voor en giet goed af.\n2. Verhit de geïnfuseerde olie en bak de aardappel met paprikapoeder in 8–10 minuten goudbruin.\n3. Voeg de spinazie toe en laat slinken.\n4. Maak vier kuiltjes, breek de eieren erin en gaar afgedekt tot het eiwit gestold is.\n5. Verdeel over twee borden en werk af met kaas en bieslook.','Origineel recept, ontwikkeld en geschreven door Fodmap Tracker.','Samengesteld zonder ui of knoflook. Gebruik echte knoflook-geïnfuseerde olie zonder stukjes knoflook en verdeel het recept in twee porties.',true),
('Kiwi-blauwebes overnight oats','Fris ontbijt met haver, lactosevrije yoghurt, groene kiwi en blauwe bes.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,10,E'80 g havermout\n200 g lactosevrije yoghurt\n120 ml lactosevrije melk of amandelmelk zonder inuline\n2 groene kiwi’s\n80 g blauwe bessen\n1 el chiazaad\n2 tl pure ahornsiroop\n½ tl kaneel',E'1. Meng havermout, yoghurt, melk, chia, ahornsiroop en kaneel.\n2. Verdeel over twee afsluitbare potjes en zet minimaal 6 uur koud.\n3. Schil en snijd de kiwi vlak voor het eten.\n4. Verdeel kiwi en blauwe bessen over de potjes.','Origineel recept, ontwikkeld en geschreven door Fodmap Tracker.','Fruitporties zijn bewust over twee kommen verdeeld. Controleer plantaardige melk op inuline, cichoreiwortel, FOS en andere toegevoegde FODMAP-vezels.',true),
('Krokante quinoa-kipsalade','Kleurrijke lunch met quinoa, kip, komkommer, wortel en frisse sinaasappeldressing.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,30,E'120 g quinoa\n250 g kipfilet\n1 wortel, in linten\n½ komkommer, in halve maantjes\n80 g babyspinazie\n1 sinaasappel\n1 el knoflook-geïnfuseerde olijfolie\n1 el pompoenpitten\n1 tl Dijonmosterd zonder ui of knoflook\nPeper en zout',E'1. Kook de quinoa, laat goed uitdampen en afkoelen.\n2. Bak de gekruide kip in de helft van de olie gaar en snijd in repen.\n3. Rasp de helft van de sinaasappelschil en pers twee eetlepels sap uit. Klop met mosterd en de overige olie tot dressing.\n4. Meng quinoa, wortel, komkommer en spinazie.\n5. Verdeel over twee kommen en voeg kip, pompoenpitten en dressing toe.','Origineel recept, ontwikkeld en geschreven door Fodmap Tracker.','Controleer mosterd op ui of knoflook. De aangegeven hoeveelheid sinaasappel wordt als smaakmaker over twee porties verdeeld.',true),
('Frisse tonijn-aardappelsalade','Vullende lunch met tonijn, aardappel, sperzieboon, olijf en citroen.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,30,E'500 g krielaardappelen, gehalveerd\n1 blik tonijn op water, uitgelekt (ca. 145 g)\n160 g sperziebonen\n½ komkommer, in blokjes\n40 g groene olijven, gehalveerd\n2 el bieslook\n1½ el olijfolie\n1 el citroensap\n1 tl Dijonmosterd zonder ui of knoflook\nPeper en zout',E'1. Kook de aardappelen in 12–15 minuten gaar.\n2. Kook de sperziebonen de laatste 6 minuten mee en laat alles afkoelen.\n3. Klop olie, citroen, mosterd, peper en zout tot dressing.\n4. Schep aardappel, bonen, komkommer, olijf, tonijn en bieslook voorzichtig om.\n5. Verdeel over twee borden en lepel de dressing erover.','Origineel recept, ontwikkeld en geschreven door Fodmap Tracker.','Kies naturel tonijn en controleer mosterd en gekruide olijven op ui of knoflook.',true),
('Citroen-kruidenkip met geroosterde groenten','Comfortabele ovenmaaltijd met kip, aardappel, wortel en sperzieboon.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,4,50,E'600 g kipdijfilet zonder marinade\n800 g aardappelen, in parten\n400 g wortelen, in schuine stukken\n240 g sperziebonen\n2½ el knoflook-geïnfuseerde olijfolie\n1 citroen\n2 tl gedroogde tijm\n1 tl gerookt paprikapoeder\n2 el verse peterselie\nPeper en zout',E'1. Verwarm de oven voor op 210 °C.\n2. Meng aardappel en wortel met twee derde van de olie, tijm, paprika, peper en zout. Rooster 20 minuten.\n3. Wrijf de kip in met de resterende olie, citroenrasp en peper. Leg tussen de groenten en rooster nog 20–25 minuten.\n4. Kook of stoom ondertussen de sperziebonen.\n5. Controleer of de kip gaar is, besprenkel met citroensap en verdeel met peterselie over vier borden.','Origineel recept, ontwikkeld en geschreven door Fodmap Tracker.','Gebruik ongemarineerde kip; kant-en-klare marinades bevatten vaak ui of knoflook. Verdeel de schaal in vier porties.',true),
('Kabeljauw met romige polenta en spinazie','Zachte polenta met citroenkabeljauw, spinazie en tomaat.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,4,35,E'4 kabeljauwfilets van ca. 150 g\n200 g fijne polenta\n750 ml water\n250 ml lactosevrije melk\n300 g babyspinazie\n250 g cherrytomaten, gehalveerd\n50 g Parmezaan, fijngeraspt\n2 el knoflook-geïnfuseerde olijfolie\n1 citroen\n2 el dille\nPeper en zout',E'1. Verwarm de oven voor op 190 °C. Leg de kabeljauw in een ovenschaal met één eetlepel olie, citroenrasp, peper en zout. Bak 12–15 minuten.\n2. Breng water en melk aan de kook. Strooi de polenta al kloppend erin en kook volgens de verpakking.\n3. Roer Parmezaan door de polenta.\n4. Bak tomaat kort in de resterende olie, voeg spinazie toe en laat slinken.\n5. Verdeel polenta, groenten en vis over vier borden en werk af met dille en citroensap.','Origineel recept, ontwikkeld en geschreven door Fodmap Tracker.','Kies naturel vis en lactosevrije melk. Controleer instantpolenta of bouillonvarianten op ui, knoflook en inuline.',true),
('Gember-sesam tofubowl','Plantaardige rijstkom met stevige tofu, paksoi, wortel en gember.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,35,E'300 g stevige tofu, goed uitgelekt\n150 g jasmijnrijst\n2 kleine paksoi, grof gesneden\n2 wortelen, in dunne reepjes\n½ komkommer, in linten\n1 el knoflook-geïnfuseerde olie\n1 el sesamolie\n2 el sojasaus zonder ui of knoflook\n2 tl rijstazijn\n2 tl verse gember, geraspt\n1 el sesamzaad',E'1. Kook de rijst volgens de verpakking.\n2. Dep de tofu droog, snijd in blokjes en bak goudbruin in de geïnfuseerde olie.\n3. Voeg wortel, paksoi en gember toe en roerbak 4–5 minuten.\n4. Meng sojasaus, sesamolie en rijstazijn en schep door tofu en groenten.\n5. Verdeel rijst en komkommer over twee kommen, voeg de tofu toe en bestrooi met sesam.','Origineel recept, ontwikkeld en geschreven door Fodmap Tracker.','Gebruik stevige, uitgelekte tofu; zijde-tofu heeft een ander FODMAP-profiel. Controleer sojasaus en smaakmakers op ui of knoflook.',true),
('Aardbei-yoghurt bark','Koud tussendoortje van lactosevrije yoghurt, aardbei en pompoenpit.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,8,15,E'400 g dikke lactosevrije yoghurt\n160 g aardbeien, in dunne plakjes\n30 g pompoenpitten\n2 el pure ahornsiroop\n1 tl vanille-extract',E'1. Bekleed een kleine bakplaat of schaal met bakpapier.\n2. Meng yoghurt, ahornsiroop en vanille en strijk uit tot een laag van circa 1 cm.\n3. Verdeel aardbei en pompoenpitten erover.\n4. Vries minimaal 4 uur in.\n5. Breek in acht stukken en bewaar afgesloten in de vriezer.','Origineel recept, ontwikkeld en geschreven door Fodmap Tracker.','Eén stuk is één portie. Controleer yoghurt en vanille-extract op inuline, cichoreiwortel of andere toegevoegde vezels.',true)
